def __str__(self):
    try:
        return self._value.decode(self.encoding)

    except UnicodeDecodeError as exc:
        raise error.PyAsn1UnicodeDecodeError(
            "Can't decode string '%s' with '%s' codec at "
            "'%s'" % (self._value, self.encoding,
                        self.__class__.__name__), exc
        )
